add('404','Page Not Found | FM Studios Preview','Return to the FM Studios website preview.',mast('Let’s find<br><em>your way back.</em>','That preview page is not available. Explore the homepage or choose a lesson.','Page not found')+'<section class="wrap section-space">'+link('index.html','Back to the homepage '+arrow(),'button')+'</section>')

def render(p):
    current=p['slug']
    section = 'lessons' if current in [i['slug'] for i in instruments]+['accelerated-strings-lab'] else 'locations' if current in [l['slug'] for l in locations]+['inhomelessons'] else current
    def nav(name,path):
        slug=path.replace('.html','')
        state='page' if current==slug else 'true' if section==slug else None
        result=link(path,name,'nav-link'+(' active' if state else ''))
        return result.replace('<a ', '<a aria-current="'+state+'" ',1) if state else result
    body='<a class="skip-link" href="#main">Skip to content</a><div class="preview-bar"><div class="wrap"><span>FM Studios · Proposed website</span>'+link('review.html?page='+quote(current),'Owner review & feedback '+arrow())+'</div></div><header class="site-header"><div class="wrap header-inner">'+link('index.html','<img src="assets/fm-studios-logo.png" width="80" height="56" alt="FM Studios"><span>Music School</span>','brand')+'<button class="menu-toggle" type="button" aria-expanded="false" aria-controls="site-navigation"><span class="menu-lines" aria-hidden="true"></span><span class="menu-label">Menu</span></button><nav id="site-navigation" aria-label="Main navigation">'+nav('Lessons','lessons.html')+nav('Locations','locations.html')+nav('Our team','ourteam.html')+nav('Contact','contact-us.html')+social_icons()+link('trial-lesson.html','Find a lesson '+arrow(),'button small')+'</nav></div></header><main id="main" tabindex="-1">'+p['body']+'</main>'
    body+='<footer class="site-footer"><div class="wrap footer-main"><div>'+link('index.html','<img src="assets/fm-studios-logo.png" width="100" height="70" alt="FM Studios Music School">','footer-brand')+'<p>Learn music. Make friends.<br>Have fun.</p></div><div><h2>Explore</h2>'+link('lessons.html','Music lessons')+link('ourteam.html','Our team')+link('accelerated-strings-lab.html','Accelerated Strings Lab')+link('trial-lesson.html','Find a trial lesson')+'</div><div><h2>Find your place</h2>'+link('new-braunfels-music-lessons.html','New Braunfels')+link('helotes-music-lessons.html','Helotes')+link('inhomelessons.html','In-home lessons')+'</div><div><h2>Let’s make music</h2>'+link('tel:+12102472247','210-247-2247')+link('mailto:hellofmstudiostx@outlook.com','Email FM Studios')+link('https://www.instagram.com/fmstudiostx/','Instagram '+arrow(),external=True)+link('https://www.facebook.com/FMStudiosTX','Facebook '+arrow(),external=True)+'</div></div><div class="wrap footer-bottom"><span>© 2026 FM Studios Music School</span><span>Website concept for owner review · '+link('review.html','Review this website')+'</span></div></footer><script src="assets/site.js?v=6" defer></script>'
    def external_hint(match):
        attrs, label = match.groups()
        if 'aria-label=' in attrs:
            attrs=re.sub(r'aria-label="([^"]+)"', lambda m: 'aria-label="'+m[1]+' (opens in a new tab)"', attrs)
        else:
            label+='<span class="visually-hidden"> (opens in a new tab)</span>'
        return '<a'+attrs+'>'+label+'</a>'
    body=re.sub(r'<a([^>]*target="_blank"[^>]*)>(.*?)</a>', external_hint, body, flags=re.S)
    body=body.replace('<em>','<span class="accent">').replace('</em>','</span>')
    body=body.replace('assets/fm-studios-logo.png','assets/fm-studios-logo.webp')
    if current=='index':
        body+='<script async src="https://www.instagram.com/embed.js"></script>'
    if current=='404':
        body=re.sub(r'(href|src)="(?!https?:|mailto:|tel:|#|/)([^"]+)"', r'\1="/fm-studios-preview/\2"', body)
    result = '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow,noarchive"><title>'+html.escape(p['title'])+'</title><meta name="description" content="'+html.escape(p['description'],quote=True)+'"><meta name="theme-color" content="#1470af"><meta property="og:type" content="website"><meta property="og:title" content="FM Studios · Proposed Website"><meta property="og:description" content="Explore the proposed FM Studios Music School redesign."><link rel="icon" href="assets/favicon.png" type="image/png"><link rel="apple-touch-icon" href="assets/apple-touch-icon.png"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&amp;family=Playfair+Display:ital,wght@0,400;0,500;0,600;1,400;1,500&amp;display=swap"><link rel="preconnect" href="https://images.squarespace-cdn.com"><link rel="stylesheet" href="assets/style.css?v=6"></head><body>'+body+'</body></html>'
    if current=='index':
        result=result.replace('</head>','<link rel="preconnect" href="https://www.instagram.com"></head>')
    if current=='404':
        result=re.sub(r'(href|src)="(?!https?:|mailto:|tel:|#|/)([^"]+)"', r'\1="/fm-studios-preview/\2"', result)
    return result

for p in pages:(DIST/(p['slug']+'.html')).write_text(render(p),encoding='utf-8')
(DIST/'robots.txt').write_text('User-agent: *\nDisallow: /\n',encoding='utf-8')
(DIST/'.nojekyll').write_text('',encoding='utf-8')
(ROOT/'page-manifest.json').write_text(json.dumps([{k:v for k,v in p.items() if k!='body'} for p in pages],indent=2),encoding='utf-8')
(ROOT/'asset-sources.json').write_text(json.dumps({'source':'FM Studios public website','images':images,'logo':'FM Studios logo supplied from existing public website','note':'Photo rights and roster should be confirmed by the owner before final production migration.'},indent=2),encoding='utf-8')
(ROOT/'README.md').write_text('''# FM Studios owner review preview

Published preview: https://sre-2025.github.io/fm-studios-preview/

Owner feedback: https://sre-2025.github.io/fm-studios-preview/review.html

A static, responsive website concept for FM Studios Music School. This is a proposed redesign; the live Squarespace site is unchanged.

## Preview locally

Serve `docs/` with a static HTTP server and open `index.html`. The site needs no package installation or build service. `build_preview.py` rebuilds the HTML; `docs/assets/style.css` and `docs/assets/site.js` are maintained directly.

## GitHub Pages

Publish from branch `main`, folder `/docs`. No custom domain is configured. Every page carries noindex/nofollow/noarchive. The project-folder robots.txt is retained, but only host-root robots.txt controls crawling; page metadata provides the preview indexing directive. These are search directives, not access controls.

## Owner approval

Open `review.html` for the feedback page. Feedback notes persist in this browser until cleared. Copy and a prepared email link are available; no feedback is sent automatically or stored on a server. Booking and inquiry links point to the school’s existing live Opus system. No analytics, advertising tags or payment integration are installed in this preview.

## Brand and social displays

The original FM palette is blue #1470af, black, white, and gray #eaeaee, verified from the live school website on October 23, 2026. The homepage uses Instagram's public profile embed and a Facebook profile card, with direct profile links and fallbacks. The public embeds load content from Meta; they do not give this site account access. Elite Foot & Ankle uses the Smash Balloon WordPress Instagram feed plugin; that plugin cannot be installed on a static GitHub Pages site. This preview uses Meta's own embed presentation instead.

## Before production migration

Confirm current teachers, instruments per location, lesson fees, trial terms, group program availability, travel policies and photo permissions. Preserve existing URLs or implement reviewed redirects. Validate Opus successful-lead and trial tracking in the actual accounts. Replace preview metadata and crawling rules only on the approved production deployment. Do not upload agency reports, credentials, customer data or internal audit notes into this repository.
''',encoding='utf-8')
(ROOT/'.gitignore').write_text('__pycache__/\n*.pyc\n.preview/\n*.zip\n',encoding='utf-8')
print(json.dumps({'pages':len(pages),'directory':str(DIST)}))
